index 0000000..662baa4
--- /dev/null
+++ b/util/labelsort/decimal.go
@@ -0,0 +1,213 @@
+// Copyright The Prometheus Authors
+// Licensed under the Apache License, Version 2.0 (the "License");
+// you may not use this file except in compliance with the License.
+// You may obtain a copy of the License at
+//
+//     http://www.apache.org/licenses/LICENSE-2.0
+//
+// Unless required by applicable law or agreed to in writing, software
+// distributed under the License is distributed on an "AS IS" BASIS,
+// WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
+// See the License for the specific language governing permissions and
+// limitations under the License.
+
+package labelsort
+
+import (
+	"math/big"
+	"strings"
+)
+
+// maxAlignDigits caps the number of digits used to line up two magnitudes that
+// are added together (see addMagnitude). Sums are only needed for compound
+// durations such as "1h30m", where the components are always within a few
+// orders of magnitude of each other; the cap only rejects absurd inputs such as
+// "1e100000h1ns", which then sort as untyped strings instead.
+const maxAlignDigits = 4096
+
+// decimal is an exact decimal number of arbitrary magnitude, held as
+//
+//	value = 0.<digits> * 10^exp
+//
+// where digits holds the significant digits only: no leading and no trailing
+// zero. An empty digits string means the value is zero, in which case neg and
+// exp carry no meaning.
+//
+// Keeping the exponent separate from the digits is what lets values such as
+// "1e1000000" be compared exactly without ever materialising them, and what
+// makes comparisons of very long digit strings lossless where float64 would
+// round them to the same value.
+type decimal struct {
+	neg    bool
+	digits string
+	exp    *big.Int
+}
+
+func (d decimal) isZero() bool { return d.digits == "" }
+
+// cmp returns -1, 0 or +1 as d is less than, equal to, or greater than o.
+func (d decimal) cmp(o decimal) int {
+	switch {
+	case d.isZero() && o.isZero():
+		return 0
+	case d.isZero():
+		if o.neg {
+			return 1
+		}
+		return -1
+	case o.isZero():
+		if d.neg {
+			return -1
+		}
+		return 1
+	case d.neg != o.neg:
+		if d.neg {
+			return -1
+		}
+		return 1
+	}
+
+	// Same sign: the exponent decides unless both values are of the same order
+	// of magnitude, in which case the digits are compared as the fractions
+	// 0.<digits>. Neither side has leading or trailing zeros, so a plain string
+	// comparison is exact, including for digit strings of different lengths.
+	c := d.exp.Cmp(o.exp)
+	if c == 0 {
+		c = strings.Compare(d.digits, o.digits)
+	}
+	if d.neg {
+		return -c
+	}
+	return c
+}
+
+// mul returns d multiplied by the positive integer f, exactly. It is used to
+// scale a magnitude by its unit, e.g. hours to nanoseconds or GiB to bytes.
+func (d decimal) mul(f *big.Int) decimal {
+	if d.isZero() {
+		return d
+	}
+	// 0.<digits> * 10^exp == <digits> * 10^(exp-len(digits)), so multiplying the
+	// digits by f and renormalising keeps the value exact.
+	m, _ := new(big.Int).SetString(d.digits, 10)
+	m.Mul(m, f)
+	return newDecimal(d.neg, m.String(), new(big.Int).Sub(d.exp, big.NewInt(int64(len(d.digits)))))
+}
+
+// addMagnitude returns the sum of the magnitudes of d and o, ignoring their
+// signs. It reports false if lining the two values up would need more than
+// maxAlignDigits digits. Callers only ever add same-signed values, so no
+// cancellation can occur.
+func addMagnitude(d, o decimal) (decimal, bool) {
+	switch {
+	case d.isZero():
+		return decimal{neg: d.neg, digits: o.digits, exp: o.exp}, true
+	case o.isZero():
+		return d, true
+	}
+
+	// Move both values to the integer form <mantissa> * 10^scale so that they
+	// can be lined up on a common scale.
+	ds := new(big.Int).Sub(d.exp, big.NewInt(int64(len(d.digits))))
+	os := new(big.Int).Sub(o.exp, big.NewInt(int64(len(o.digits))))
+
+	lo, hi := ds, os
+	loDigits, hiDigits := d.digits, o.digits
+	if lo.Cmp(hi) > 0 {
+		lo, hi = hi, lo
+		loDigits, hiDigits = hiDigits, loDigits
+	}
+
+	shift := new(big.Int).Sub(hi, lo)
+	if !shift.IsInt64() || shift.Int64() > maxAlignDigits {
+		return decimal{}, false
+	}
+
+	sum, _ := new(big.Int).SetString(hiDigits, 10)
+	sum.Mul(sum, new(big.Int).Exp(big.NewInt(10), shift, nil))
+	loMantissa, _ := new(big.Int).SetString(loDigits, 10)
+	sum.Add(sum, loMantissa)
+
+	return newDecimal(d.neg, sum.String(), lo), true
+}
+
+// newDecimal normalises mantissa * 10^scale, where mantissa is an unsigned
+// decimal digit string, into the 0.<digits> * 10^exp form.
+func newDecimal(neg bool, mantissa string, scale *big.Int) decimal {
+	significant := strings.TrimLeft(mantissa, "0")
+	digits := strings.TrimRight(significant, "0")
+	if digits == "" {
+		return decimal{}
+	}
+	// Dropping leading zeros does not change the value, so the exponent follows
+	// from the number of digits left of the trailing zeros.
+	exp := new(big.Int).Add(scale, big.NewInt(int64(len(significant))))
+	return decimal{neg: neg, digits: digits, exp: exp}
+}
+
+// scanNumber consumes the longest valid unsigned number at s[i:] and returns
+// its value together with the index just past it. A number is a digit sequence
+// with an optional fractional part and an optional decimal exponent; at least
+// one digit is required. An exponent marker that is not followed by any digit
+// is not consumed, so "1e" scans as the number 1 with "e" left over.
+func scanNumber(s string, i int) (decimal, int, bool) {
+	intStart := i
+	for i < len(s) && isDigit(s[i]) {
+		i++
+	}
+	intDigits := s[intStart:i]
+
+	var fracDigits string
+	if i < len(s) && s[i] == '.' {
+		j := i + 1
+		fracStart := j
+		for j < len(s) && isDigit(s[j]) {
+			j++
+		}
+		fracDigits = s[fracStart:j]
+		// A dot only belongs to the number if there is at least one digit on
+		// either side of it: "5." and ".5" are numbers, "." is not.
+		if intDigits != "" || fracDigits != "" {
+			i = j
+		}
+	}
+	if intDigits == "" && fracDigits == "" {
+		return decimal{}, i, false
+	}
+
+	exp := new(big.Int)
+	if i < len(s) && (s[i] == 'e' || s[i] == 'E') {
+		j := i + 1
+		negExp := false
+		if j < len(s) && (s[j] == '+' || s[j] == '-') {
+			negExp = s[j] == '-'
+			j++
+		}
+		expStart := j
+		for j < len(s) && isDigit(s[j]) {
+			j++
+		}
+		if j > expStart {
+			exp.SetString(s[expStart:j], 10)
+			if negExp {
+				exp.Neg(exp)
+			}
+			i = j
+		}
+	}
+
+	// The scanned digits represent intDigits+fracDigits * 10^(exp-len(frac)),
+	// which newDecimal turns into the normalised form.
+	exp.Sub(exp, big.NewInt(int64(len(fracDigits))))
+	return newDecimal(false, intDigits+fracDigits, exp), i, true
+}
+
+// scanSign consumes an optional leading sign at s[i:].
+func scanSign(s string, i int) (neg bool, next int) {
+	if i < len(s) && (s[i] == '+' || s[i] == '-') {
+		return s[i] == '-', i + 1
+	}
+	return false, i
+}
+
+func isDigit(c byte) bool { return c >= '0' && c <= '9' }
diff --git a/util/labelsort/labelsort.go b/util/labelsort/labelsort.go
new file mode 100644
index 0000000..0c829ec
--- /dev/null
+++ b/util/labelsort/labelsort.go
@@ -0,0 +1,360 @@
+// Copyright The Prometheus Authors
+// Licensed under the Apache License, Version 2.0 (the "License");
+// you may not use this file except in compliance with the License.
+// You may obtain a copy of the License at
+//
+//     http://www.apache.org/licenses/LICENSE-2.0
+//
+// Unless required by applicable law or agreed to in writing, software
+// distributed under the License is distributed on an "AS IS" BASIS,
+// WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
+// See the License for the specific language governing permissions and
+// limitations under the License.
+
+// Package labelsort orders label values by comparing them across several
+// value domains instead of comparing them as plain strings.
+//
+// Label values often carry a type that a lexicographic or even a natural
+// ordering gets wrong: "10ms" belongs after "2s", "1.10.0" after "1.9.0" and
+// "10.0.0.2" after "10.0.0.10" would be wrong. Package labelsort recognises the
+// most common of those representations and compares values of the same domain
+// by their meaning, while still yielding one total order over label values that
+// mix domains: values are grouped by the domain they belong to, the groups are
+// ordered by [Kind], and values that are equal within their domain fall back to
+// the natural ordering of the original strings.
+package labelsort
+
+import (
+	"math/big"
+	"net/netip"
+	"strings"
+	"time"
+	"unicode"
+	"unicode/utf8"
+)
+
+// Kind is the value domain a label value was recognised as. The values of the
+// constants define the order of the domains relative to each other: every
+// value of a smaller Kind sorts before every value of a larger one.
+type Kind int
+
+const (
+	// KindLeadingSpace is a value starting with whitespace. Such values are
+	// never interpreted as a typed value and sort before everything else.
+	KindLeadingSpace Kind = iota
+	// KindPositiveInfinity is a positive infinity, e.g. "+Inf".
+	KindPositiveInfinity
+	// KindNumber is a finite number, e.g. "-1.5" or "2.5e-3".
+	KindNumber
+	// KindNegativeInfinity is a negative infinity, e.g. "-Inf".
+	KindNegativeInfinity
+	// KindDuration is a duration, e.g. "1h30m" or "500ms".
+	KindDuration
+	// KindBytes is a byte size, e.g. "512KiB" or "1.5GB".
+	KindBytes
+	// KindSemVer is a semantic version, e.g. "v1.9.0" or "2.0.0-rc.1".
+	KindSemVer
+	// KindIP is an IPv4 or IPv6 address, e.g. "10.0.0.1" or "::1".
+	KindIP
+	// KindCIDR is an IPv4 or IPv6 prefix, e.g. "10.0.0.0/8".
+	KindCIDR
+	// KindTimestamp is a date or timestamp, e.g. "2024-05-06T07:08:09Z".
+	KindTimestamp
+	// KindString is any value that is not recognised as one of the above.
+	KindString
+)
+
+func (k Kind) String() string {
+	if k < KindLeadingSpace || k > KindString {
+		return "unknown"
+	}
+	return [...]string{
+		"leading space", "positive infinity", "number", "negative infinity", "duration",
+		"bytes", "semantic version", "ip", "cidr", "timestamp", "string",
+	}[k]
+}
+
+// Value is a label value together with the domain it was recognised as. Parse
+// it once and compare it many times to keep sorting cheap.
+type Value struct {
+	kind Kind
+	s    string // The original label value, used to break ties.
+
+	num  decimal    // Number, duration in nanoseconds, or size in bytes.
+	addr netip.Addr // Address of an IP, or network address of a CIDR.
+	bits int        // Prefix length of a CIDR.
+	ts   time.Time  // Timestamp.
+	sv   *semVer    // Semantic version.
+}
+
+// Compare compares the label values a and b. It returns a negative number if a
+// sorts before b, a positive number if a sorts after b, and 0 only if a and b
+// are identical.
+//
+// Use [Parse] and [Value.Compare] instead when a value is compared repeatedly,
+// as sorting does.
+func Compare(a, b string) int {
+	return Parse(a).Compare(Parse(b))
+}
+
+// Parse recognises the domain of a label value.
+func Parse(s string) Value {
+	if hasLeadingSpace(s) {
+		return Value{kind: KindLeadingSpace, s: s}
+	}
+	if kind, ok := parseInfinity(s); ok {
+		return Value{kind: kind, s: s}
+	}
+	if num, ok := parseNumber(s); ok {
+		return Value{kind: KindNumber, s: s, num: num}
+	}
+	if num, ok := parseDuration(s); ok {
+		return Value{kind: KindDuration, s: s, num: num}
+	}
+	if num, ok := parseBytes(s); ok {
+		return Value{kind: KindBytes, s: s, num: num}
+	}
+	// A version starts with its major version, an address holds a dot or a
+	// colon and a prefix a slash. Checking that here keeps ordinary strings
+	// from being run through the parsers of every remaining domain.
+	if core := strings.TrimPrefix(s, "v"); core != "" && isDigit(core[0]) {
+		if sv, ok := parseSemVer(s); ok {
+			return Value{kind: KindSemVer, s: s, sv: sv}
+		}
+	}
+	if strings.ContainsAny(s, ".:") {
+		if addr, err := netip.ParseAddr(s); err == nil {
+			return Value{kind: KindIP, s: s, addr: addr}
+		}
+		if strings.IndexByte(s, '/') >= 0 {
+			if prefix, err := netip.ParsePrefix(s); err == nil {
+				// Comparing masked addresses keeps CIDRs ordered by the network
+				// they describe, independently of which address inside it was
+				// written down.
+				return Value{kind: KindCIDR, s: s, addr: prefix.Masked().Addr(), bits: prefix.Bits()}
+			}
+		}
+	}
+	if ts, ok := parseTimestamp(s); ok {
+		return Value{kind: KindTimestamp, s: s, ts: ts}
+	}
+	return Value{kind: KindString, s: s}
+}
+
+// Kind returns the domain v was recognised as.
+func (v Value) Kind() Kind { return v.kind }
+
+// Compare compares v and o as described by [Compare].
+func (v Value) Compare(o Value) int {
+	if v.kind != o.kind {
+		if v.kind < o.kind {
+			return -1
+		}
+		return 1
+	}
+
+	var c int
+	switch v.kind {
+	case KindNumber, KindDuration, KindBytes:
+		c = v.num.cmp(o.num)
+	case KindSemVer:
+		c = v.sv.cmp(o.sv)
+	case KindIP:
+		// netip orders IPv4 before IPv6, and an IPv4-mapped IPv6 address
+		// counts as IPv6.
+		c = v.addr.Compare(o.addr)
+	case KindCIDR:
+		if c = v.addr.Compare(o.addr); c == 0 {
+			// Same network address: the shorter, less specific prefix first.
+			c = v.bits - o.bits
+		}
+	case KindTimestamp:
+		c = v.ts.Compare(o.ts)
+	}
+	if c != 0 {
+		return c
+	}
+
+	// Values that are equal in their domain, as well as the domains that have
+	// no ordering of their own, are ordered by the original strings.
+	return Natural(v.s, o.s)
+}
+
+// hasLeadingSpace reports whether s starts with a whitespace character.
+func hasLeadingSpace(s string) bool {
+	if s == "" {
+		return false
+	}
+	r, _ := utf8.DecodeRuneInString(s)
+	return unicode.IsSpace(r)
+}
+
+// parseInfinity recognises an infinity, e.g. "Inf", "+Inf" or "-infinity".
+func parseInfinity(s string) (Kind, bool) {
+	neg, i := scanSign(s, 0)
+	switch rest := s[i:]; {
+	case !strings.EqualFold(rest, "inf") && !strings.EqualFold(rest, "infinity"):
+		return 0, false
+	case neg:
+		return KindNegativeInfinity, true
+	default:
+		return KindPositiveInfinity, true
+	}
+}
+
+// parseNumber recognises a finite number with an optional sign and an optional
+// decimal exponent, e.g. "+1.5" or "2.5e-3". Note that "NaN" is deliberately
+// not a number: it has no place in an ordering.
+func parseNumber(s string) (decimal, bool) {
+	neg, i := scanSign(s, 0)
+	num, i, ok := scanNumber(s, i)
+	if !ok || i != len(s) {
+		// Anything left over means this is not a number: "1e" in particular is
+		// the number 1 followed by a stray exponent marker.
+		return decimal{}, false
+	}
+	num.neg = neg
+	return num, true
+}
+
+// durationUnits maps the duration units to their length in nanoseconds. Units
+// that are a prefix of another one must come last, as the first match wins.
+var durationUnits = []struct {
+	unit  string
+	nanos int64
+}{
+	{"ns", 1},
+	{"us", int64(time.Microsecond)},
+	{"µs", int64(time.Microsecond)}, // U+00B5, micro sign.
+	{"μs", int64(time.Microsecond)}, // U+03BC, Greek small letter mu.
+	{"ms", int64(time.Millisecond)},
+	{"s", int64(time.Second)},
+	{"m", int64(time.Minute)},
+	{"h", int64(time.Hour)},
+	{"d", 24 * int64(time.Hour)},
+	{"w", 7 * 24 * int64(time.Hour)},
+	{"y", 365 * 24 * int64(time.Hour)},
+}
+
+// parseDuration recognises a duration as a sequence of magnitudes with a unit,
+// e.g. "500ms", "1h30m" or "-1.5e3s", and returns it in nanoseconds. The sign
+// applies to the duration as a whole.
+func parseDuration(s string) (decimal, bool) {
+	neg, i := scanSign(s, 0)
+
+	total := decimal{neg: neg}
+	for n := 0; ; n++ {
+		if i == len(s) {
+			// At least one magnitude with a unit is required, and a bare
+			// number is a number rather than a duration.
+			return total, n > 0
+		}
+
+		num, next, ok := scanNumber(s, i)
+		if !ok {
+			return decimal{}, false
+		}
+		i = next
+
+		unit := int64(0)
+		for _, u := range durationUnits {
+			if strings.HasPrefix(s[i:], u.unit) {
+				unit, i = u.nanos, i+len(u.unit)
+				break
+			}
+		}
+		if unit == 0 {
+			return decimal{}, false
+		}
+
+		total, ok = addMagnitude(total, num.mul(big.NewInt(unit)))
+		if !ok {
+			return decimal{}, false
+		}
+	}
+}
+
+// bytePrefixes are the unit prefixes of a byte size, in increasing order of
+// magnitude.
+const bytePrefixes = "kmgtpezy"
+
+// parseBytes recognises a byte size, e.g. "1kB", "512KiB" or "-1.5e3MB", and
+// returns it in bytes. The unit is recognised regardless of case; both the "B"
+// suffix and the "i" of the binary multiples are optional. A magnitude without
+// a unit is a number, not a byte size.
+func parseBytes(s string) (decimal, bool) {
+	neg, i := scanSign(s, 0)
+
+	num, i, ok := scanNumber(s, i)
+	if !ok {
+		return decimal{}, false
+	}
+
+	unit := strings.ToLower(s[i:])
+	if unit == "" {
+		return decimal{}, false
+	}
+
+	// A prefix letter scales the magnitude; a unit without one has to be a
+	// plain "B".
+	exp := strings.IndexByte(bytePrefixes, unit[0]) + 1
+	if exp > 0 {
+		unit = unit[1:]
+	} else if unit != "b" {
+		return decimal{}, false
+	}
+
+	base := int64(1000)
+	if strings.HasPrefix(unit, "i") {
+		base, unit = 1024, unit[1:]
+	}
+	switch {
+	case unit != "" && unit != "b":
+		return decimal{}, false
+	case s[i] == 'e' || s[i] == 'E':
+		// A bare "e" or "E" is an exponent marker that lost its digits rather
+		// than the exabyte unit, so that "1e" stays an untyped string. "1EB"
+		// and "1Ei" are byte sizes.
+		if len(s[i:]) == 1 {
+			return decimal{}, false
+		}
+	}
+
+	num.neg = neg
+	return num.mul(new(big.Int).Exp(big.NewInt(base), big.NewInt(int64(exp)), nil)), true
+}
+
+// timestampLayouts are the timestamp formats recognised in label values. A
+// timestamp without a zone is read as UTC.
+var timestampLayouts = []string{
+	time.RFC3339Nano,
+	"2006-01-02T15:04:05.999999999",
+	"2006-01-02 15:04:05.999999999Z07:00",
+	"2006-01-02 15:04:05.999999999",
+	"2006-01-02T15:04Z07:00",
+	"2006-01-02T15:04",
+	"2006-01-02 15:04",
+	"2006-01-02",
+	time.RFC1123Z,
+	time.RFC1123,
+}
+
+// parseTimestamp recognises a date or timestamp.
+func parseTimestamp(s string) (time.Time, bool) {
+	// Every recognised layout starts with either a four-digit year or a
+	// weekday name followed by a comma. Checking that first keeps the common
+	// case of an ordinary string from running through all the layouts.
+	switch {
+	case len(s) > 4 && s[4] == '-' && allDigits(s[:4]):
+	case len(s) > 3 && s[3] == ',':
+	default:
+		return time.Time{}, false
+	}
+
+	for _, layout := range timestampLayouts {
+		if ts, err := time.Parse(layout, s); err == nil {
+			return ts, true
+		}
+	}
+	return time.Time{}, false
+}
