+		" ", "0.0", "+0", "1.0.0-alpha.10", "1.0.0-alpha.2", "01", "1e0", "1E3", "1kb", "1KB", "0B",
+		"1h30m0s", "90m", "1.5h", "::ffff:0.0.0.0", "0.0.0.0/0", "v0.0.1", "2024-05-06T00:00:00Z",
+		"1e1000000001", "-1e1000000000", "1e-1000000000", "nan", "+", "-", "e", "Inf ", " Inf",
+	})
+
+	for _, a := range values {
+		for _, b := range values {
+			ab, ba := Compare(a, b), Compare(b, a)
+			require.Equalf(t, ab == 0, a == b, "only identical values may compare equal: %q, %q", a, b)
+			require.Equalf(t, sign(ab), -sign(ba), "comparison is not antisymmetric: %q, %q", a, b)
+
+			for _, c := range values {
+				if ab < 0 && Compare(b, c) < 0 {
+					require.Negativef(t, Compare(a, c), "comparison is not transitive: %q < %q < %q", a, b, c)
+				}
+			}
+		}
