+func TestCompareTypedValues(t *testing.T) {
+	for _, tc := range []struct {
+		a, b string
+		want int
+		why  string
+	}{
+		// Numbers keep their order no matter how big or precise they are.
+		{a: "9007199254740993", b: "9007199254740992", want: 1, why: "beyond float64 precision"},
+		{a: "1e1000000000", b: "9e999999999", want: 1, why: "beyond float64 range"},
+		{a: "0.1000000000000000000000000001", b: "0.1", want: 1},
+		{a: "1e3", b: "1000", want: -1, why: "same number, natural order of the strings"},
+		{a: "+1", b: "1", want: -1, why: "equal numbers fall back to natural order"},
+
+		// Durations and byte sizes are compared by their magnitude.
+		{a: "1000ms", b: "1s", want: 1, why: "same duration, natural order of the strings"},
+		{a: "90m", b: "1h30m", want: 1, why: "same duration, natural order of the strings"},
+		{a: "500ms", b: "1m", want: -1},
+		{a: "1.5e3ms", b: "1s", want: 1},
+		{a: "-1h", b: "1ns", want: -1},
+		{a: "1000000000000000000000000001ns", b: "1000000000000000000000000000ns", want: 1, why: "exact beyond float64"},
+		{a: "1KiB", b: "1kB", want: 1, why: "1024 bytes against 1000"},
+		{a: "1024B", b: "1KiB", want: 1, why: "same size, natural order of the strings"},
+		{a: "1e400YB", b: "1e400ZB", want: 1},
+
+		// Semantic versions order by precedence, not lexically.
+		{a: "1.10.0", b: "1.9.0", want: 1},
+		{a: "v1.10.0", b: "1.10.0", want: 1, why: "same version, natural order of the strings"},
+		{a: "1.0.0", b: "1.0.0-rc.1", want: 1, why: "a pre-release comes before the release"},
+		{a: "1.0.0-alpha.11", b: "1.0.0-alpha.2", want: 1},
+		{a: "1.0.0-alpha", b: "1.0.0-alpha.1", want: -1},
+		{a: "1.0.0-1", b: "1.0.0-alpha", want: -1, why: "numeric identifiers come first"},
+		{a: "1.0.0+b", b: "1.0.0+a", want: 1, why: "build metadata is ignored, natural order decides"},
+
+		// IPv4 sorts before IPv6, including IPv4-mapped IPv6.
+		{a: "255.255.255.255", b: "::", want: -1},
+		{a: "255.255.255.255", b: "::ffff:0.0.0.0", want: -1},
+		{a: "10.0.0.10", b: "10.0.0.2", want: 1},
+		{a: "10.0.0.0/8", b: "10.0.0.0/16", want: -1, why: "the less specific prefix first"},
+		{a: "10.0.0.1/8", b: "10.0.0.0/16", want: -1, why: "same network address, less specific first"},
+		{a: "255.255.255.255/32", b: "::/0", want: -1},
+		{a: "10.0.0.1", b: "10.0.0.0/8", want: -1, why: "addresses sort before prefixes"},
+
+		// Timestamps order by the instant they denote.
+		{a: "2024-05-06T07:08:09Z", b: "2024-05-06T09:08:09+03:00", want: 1},
+		{a: "2024-05-06T00:00:00Z", b: "2024-05-06", want: 1, why: "same instant, natural order of the strings"},
+		{a: "2024-05-06", b: "2024-05-06T07:08:09Z", want: -1},
+
+		// Values of different domains order by their domain.
+		{a: " 9", b: "+Inf", want: -1, why: "leading whitespace sorts before everything"},
+		{a: "+Inf", b: "1e1000000000", want: -1},
+		{a: "-Inf", b: "-1e1000000000", want: 1, why: "negative infinity sorts after the finite numbers"},
+		{a: "-Inf", b: "1ns", want: -1},
+		{a: "1y", b: "1B", want: -1, why: "durations sort before byte sizes"},
+		{a: "1YB", b: "0.0.1", want: -1, why: "byte sizes sort before versions"},
+		{a: "9.9.9", b: "0.0.0.0", want: -1, why: "versions sort before addresses"},
+		{a: "2024-05-06", b: "foo", want: -1, why: "timestamps sort before untyped strings"},
+		{a: "NaN", b: "1e", want: 1, why: "neither is typed, natural order decides"},
+		{a: "", b: "foo", want: -1, why: "an empty value is untyped"},
+		{a: "", b: "0", want: 1, why: "an empty value is untyped"},
+	} {
+		t.Run(fmt.Sprintf("%q/%q", tc.a, tc.b), func(t *testing.T) {
+			got := Compare(tc.a, tc.b)
+			require.Equal(t, tc.want, sign(got), tc.why)
+			require.Equal(t, -tc.want, sign(Compare(tc.b, tc.a)), tc.why)
+		})
+	}
+}
+
+func TestNatural(t *testing.T) {
+	for _, tc := range []struct {
+		a, b string
+		want int
+	}{
+		{a: "", b: "", want: 0},
+		{a: "foo", b: "foo", want: 0},
+		{a: "", b: "a", want: -1},
+		{a: "a2", b: "a10", want: -1},
+		{a: "a10", b: "a9b", want: 1},
+		{a: "4m5", b: "4m600", want: -1},
+		{a: "4m600", b: "4m1000", want: -1},
+		{a: "x1y2", b: "x1y10", want: -1},
+		{a: "1", b: "01", want: 1},
+		{a: "a1", b: "a1b", want: -1},
+		{a: "a", b: "B", want: 1},
+		// Digit runs are compared numerically however long they are.
+		{a: strings.Repeat("9", 100), b: strings.Repeat("9", 99) + "8", want: 1},
+		{a: "v" + strings.Repeat("0", 50) + "2", b: "v2", want: -1},
+	} {
+		t.Run(fmt.Sprintf("%q/%q", tc.a, tc.b), func(t *testing.T) {
+			require.Equal(t, tc.want, sign(Natural(tc.a, tc.b)))
+			require.Equal(t, -tc.want, sign(Natural(tc.b, tc.a)))
+		})
+	}
+}
+
+func sign(i int) int {
+	switch {
+	case i < 0:
+		return -1
+	case i > 0:
+		return 1
+	}
+	return 0
+}
+
+func BenchmarkCompare(b *testing.B) {
+	for _, values := range [][2]string{
+		{"10", "9"},
+		{"1h30m", "500ms"},
+		{"512KiB", "1.5GB"},
+		{"1.10.0", "1.9.0"},
+		{"10.0.0.10", "10.0.0.2"},
+		{"instance-a", "instance-b"},
+	} {
+		b.Run(values[0], func(b *testing.B) {
+			for range b.N {
+				Compare(values[0], values[1])
+			}
+		})
+	}
+}
