+// Natural compares a and b in natural sort order, i.e. runs of digits are
+// compared by their numeric value and everything else byte by byte, so that
+// "foo2" sorts before "foo10". Digit runs are compared without converting them,
+// so arbitrarily long runs keep their order.
+//
+// Strings that are equal in natural order but not identical, such as "01" and
+// "1", are ordered by their bytes. Natural therefore returns 0 only for
+// identical strings, which makes it a total order.
+func Natural(a, b string) int {
+	i, j := 0, 0
+	for i < len(a) && j < len(b) {
+		if isDigit(a[i]) && isDigit(b[j]) {
+			ai, bj := i, j
+			for i < len(a) && isDigit(a[i]) {
+				i++
+			}
+			for j < len(b) && isDigit(b[j]) {
+				j++
+			}
+			if c := compareDigitRuns(a[ai:i], b[bj:j]); c != 0 {
+				return c
+			}
+			continue
+		}
+		if a[i] != b[j] {
+			if a[i] < b[j] {
+				return -1
+			}
+			return 1
+		}
+		i++
+		j++
+	}
+
+	switch {
+	case i < len(a):
+		return 1
+	case j < len(b):
+		return -1
+	}
+	return strings.Compare(a, b)
+}
+
+// compareDigitRuns compares two runs of digits numerically.
+func compareDigitRuns(a, b string) int {
+	a = strings.TrimLeft(a, "0")
+	b = strings.TrimLeft(b, "0")
+	if len(a) != len(b) {
+		if len(a) < len(b) {
+			return -1
+		}
+		return 1
+	}
+	return strings.Compare(a, b)
+}
