+package labelsort
+
+import "strings"
+
+// semVer is a version as defined by https://semver.org/. Build metadata is
+// validated but not kept: it is ignored when determining precedence.
+type semVer struct {
+	major, minor, patch string // Numeric identifiers, without leading zeros.
+	pre                 string // Pre-release identifiers, without the leading "-".
+	hasPre              bool
+}
+
+// parseSemVer parses a semantic version, allowing the customary "v" prefix.
+// Anything that is not a complete major.minor.patch version is rejected.
+func parseSemVer(s string) (*semVer, bool) {
+	s = strings.TrimPrefix(s, "v")
+
+	core := s
+	build := ""
+	if i := strings.IndexByte(core, '+'); i >= 0 {
+		core, build = core[:i], core[i+1:]
+		if !validIdentifiers(build, true) {
+			return nil, false
+		}
+	}
+
+	v := semVer{}
+	if i := strings.IndexByte(core, '-'); i >= 0 {
+		core, v.pre, v.hasPre = core[:i], core[i+1:], true
+		if !validIdentifiers(v.pre, false) {
+			return nil, false
+		}
+	}
+
+	parts := strings.Split(core, ".")
+	if len(parts) != 3 {
+		return nil, false
+	}
+	for _, p := range parts {
+		if !numericIdentifier(p) {
+			return nil, false
+		}
+	}
+	v.major, v.minor, v.patch = parts[0], parts[1], parts[2]
+	return &v, true
+}
+
+// cmp returns -1, 0 or +1 as v precedes, equals or follows o. Versions that
+// differ only in build metadata compare equal, as required by semver.
+func (v *semVer) cmp(o *semVer) int {
+	for _, ids := range [][2]string{{v.major, o.major}, {v.minor, o.minor}, {v.patch, o.patch}} {
+		if c := compareDigitRuns(ids[0], ids[1]); c != 0 {
+			return c
+		}
+	}
+
+	switch {
+	case !v.hasPre && !o.hasPre:
+		return 0
+	case !v.hasPre:
+		// A version without a pre-release takes precedence over one with it.
+		return 1
+	case !o.hasPre:
+		return -1
+	}
+	return comparePreRelease(v.pre, o.pre)
+}
+
+func comparePreRelease(a, b string) int {
+	aIDs, bIDs := strings.Split(a, "."), strings.Split(b, ".")
+	for i := 0; i < len(aIDs) && i < len(bIDs); i++ {
+		aID, bID := aIDs[i], bIDs[i]
+		aNum, bNum := allDigits(aID), allDigits(bID)
+		switch {
+		case aNum && bNum:
+			if c := compareDigitRuns(aID, bID); c != 0 {
+				return c
+			}
+		case aNum:
+			// Numeric identifiers always have lower precedence than
+			// alphanumeric ones.
+			return -1
+		case bNum:
+			return 1
+		default:
+			if c := strings.Compare(aID, bID); c != 0 {
+				return c
+			}
+		}
+	}
+	// A larger set of pre-release fields has a higher precedence.
+	switch {
+	case len(aIDs) < len(bIDs):
+		return -1
+	case len(aIDs) > len(bIDs):
+		return 1
+	}
+	return 0
+}
+
+// validIdentifiers reports whether s is a dot-separated list of non-empty
+// identifiers of [0-9A-Za-z-]. Outside of build metadata, purely numeric
+// identifiers must not carry leading zeros.
+func validIdentifiers(s string, isBuild bool) bool {
+	if s == "" {
+		return false
+	}
+	for _, id := range strings.Split(s, ".") {
+		if id == "" {
+			return false
+		}
+		for i := 0; i < len(id); i++ {
+			if c := id[i]; !isDigit(c) && !isAlpha(c) && c != '-' {
+				return false
+			}
+		}
+		if !isBuild && allDigits(id) && !numericIdentifier(id) {
+			return false
+		}
+	}
+	return true
+}
+
+// numericIdentifier reports whether s is a semver numeric identifier: digits
+// only, and no leading zero unless the identifier is "0" itself.
+func numericIdentifier(s string) bool {
+	if !allDigits(s) {
+		return false
+	}
+	return len(s) == 1 || s[0] != '0'
+}
+
+func allDigits(s string) bool {
+	if s == "" {
+		return false
+	}
+	for i := 0; i < len(s); i++ {
+		if !isDigit(s[i]) {
+			return false
+		}
+	}
+	return true
+}
+
+func isAlpha(c byte) bool { return c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' }
